import unittest
from catalog import visible
from paging import page
class Contract(unittest.TestCase):
    def test_missing(self): self.assertEqual(visible([{}, {"enabled":1}]), [])
    def test_flag(self): self.assertEqual(visible([{"enabled":True}, {"enabled":False}]), [{"enabled":True}])
    def test_slice(self): self.assertEqual(page([0,1,2,3], 1, 2), [1,2])
    def test_zero(self): self.assertEqual(page([0,1], 1, 0), [])
    def test_invalid(self):
        with self.assertRaises(ValueError): page([], -1, 2)
    def test_integration(self): self.assertEqual(page(visible([{}, {"enabled":True,"id":1}, {"enabled":True,"id":2}]), 1, 1), [{"enabled":True,"id":2}])

